for p in pathlib.Path('exllamav3').rglob('*.py'):
 try: s=p.read_text(); t=ast.parse(s)
 except (SyntaxError,UnicodeError): continue
 for n in ast.walk(t):
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=='Linear':
   print(str(p)+':'+str(n.lineno)+' '+ast.get_source_segment(s,n))

